// Emits the Go artifact: zz_categories.gen.go for package `domain`.
//
// Design: the generated file is SELF-CONTAINED and import-free, and carries
// only what the backend consumes — the slug→label dictionary (the
// materialization snapshot resolves a slug to its label, ADR 0049 §1).
// UI metadata (icon, color, canonical UI order) is a frontend concern and
// lives only in the TS artifact. Lookup goes by linear scan over the ordered
// slice — the catalog is 40 entries, and a single source of the data in the
// file beats a duplicated slug→label map.

const HEADER = `// Code generated by tools/payment-categories/generate.mjs from catalog.json. DO NOT EDIT.
//
// zz_categories.gen.go — сгенерировано из tools/payment-categories/catalog.json.
// НЕ редактировать вручную. Чтобы регенерировать:
//
//\tcd tools/payment-categories && node generate.mjs
//
// (или из корня монорепо: make categories-gen)
//
// Самодостаточный модуль без импортов: словарь дефолтного каталога категорий
// платежей для бекенда — слаг (каноническая ссылка из БД) → название (снапшот
// в операцию при материализации). UI-метаданные каталога (иконка, цвет
// подложки, порядок UI) — только во фронтенд-артефакте генератора
// (features/payment-categories/lib/generated/categories.ts). Категория
// нейтральна к направлению: доход/расход выбирается на платеже, а не в каталоге.
`;

function goStr(s) {
  return JSON.stringify(s);
}

function emitEntry(cat) {
  return `\t{Slug: ${goStr(cat.slug)}, Label: ${goStr(cat.label)}},`;
}

export function emitGo(catalog) {
  const entries = catalog.categories.map(emitEntry).join('\n');

  return `${HEADER}
package domain

// CategoryCatalogEntry — запись словаря дефолтного каталога категорий
// платежей: слаг — каноническая ссылка из БД, название — источник снапшота
// category_label при материализации операции.
type CategoryCatalogEntry struct {
\tSlug  string
\tLabel string
}

// defaultCategories — словарь дефолтного каталога. Общий для всех вызовов:
// не мутировать.
var defaultCategories = []CategoryCatalogEntry{
${entries}
}

// CategoryBySlug ищет запись дефолтного каталога по слагу.
func CategoryBySlug(slug string) (CategoryCatalogEntry, bool) {
\tfor _, entry := range defaultCategories {
\t\tif entry.Slug == slug {
\t\t\treturn entry, true
\t\t}
\t}
\treturn CategoryCatalogEntry{}, false
}

// CategoryCatalogEntries возвращает все записи дефолтного каталога в
// порядке каталога. Слайс общий для всех вызовов: не мутировать.
func CategoryCatalogEntries() []CategoryCatalogEntry {
\treturn defaultCategories
}

// IsValidDefaultCategorySlug сообщает, входит ли слаг в дефолтный каталог.
func IsValidDefaultCategorySlug(slug string) bool {
\t_, ok := CategoryBySlug(slug)
\treturn ok
}
`;
}
